    // 转 3 圈：每圈读一颗新的，喊一次那一招，把结果放回总数碗里

    // 印「一共 N 条小鱼干」

    return 0;
}

items.referenceSolution:
#include <stdio.h>

int add(int a, int b) {
    return a + b;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) {
        return 1;
    }

    int total = 0;
    int i;
    for (i = 0; i < n; i++) {
        int x;
        if (scanf("%d", &x) != 1) {
            return 1;
        }
        total = add(total, x);
    }

    printf("一共 %d 条小鱼干\n", total);
    return 0;
}

